CREATE OR REPLACE FUNCTION public.log_foreign_work_export(_metadata jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr')) THEN RAISE EXCEPTION 'Report access required' USING ERRCODE='42501'; END IF; INSERT INTO public.audit_log(actor_id,entity_type,entity_id,action,new_values,reason,actor_type,source) VALUES(auth.uid(),'foreign_work_export',gen_random_uuid()::text,'create',_metadata,'Utlandsrapport XLSX',CASE WHEN public.has_role(auth.uid(),'admin') THEN 'admin' ELSE 'user' END,'app'); END $$;
ALTER TABLE public.foreign_work_documents ADD COLUMN expiry_warning_days integer NOT NULL DEFAULT 30 CHECK(expiry_warning_days BETWEEN 0 AND 365);
DROP TRIGGER trg_audit_fw_docs_upd ON public.foreign_work_documents;
CREATE TRIGGER trg_audit_fw_docs_upd AFTER UPDATE ON public.foreign_work_documents FOR EACH ROW EXECUTE FUNCTION public.audit_row_change('foreign_work_document','doc_type','installer_id','doc_type','countries','valid_from','valid_to','status','reference_number','voided_at','document_id','notes','expiry_warning_days');
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.foreign_work_my_documents(uuid)'::regprocedure); d:=replace(d,'''status'',d.status','''status'',d.status,''expiry_warning_days'',d.expiry_warning_days'); EXECUTE d; END $$;